window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b8d4323d9df0d70"]={"versions": [{"id": "FIG-7b8d4323d9df0d70", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-Standard (Software Component Template). Das Diagramm stellt die strukturelle Verankerung von Ausführungseinheiten innerhalb der Softwarekomponenten-Hierarchie dar und verdeutlicht das Entwurfsprinzip, dass nur atomare Software-Komponententypen ein internes Ausführungsverhalten definieren dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Spezialisierungen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ComponentType</code> (Stereotyp «atpType», abgeleitet von <code>ARElement</code>): Abstrakte Basisklasse für alle Software-Komponententypen.</li>\n<li><code>CompositionType</code> (Stereotyp «atpType»): Spezialisierung von <code>ComponentType</code> zur hierarchischen Kapselung und Verschachtelung von Komponenten, besitzt kein eigenes <code>InternalBehavior</code>.</li>\n<li><code>AtomicSoftwareComponentType</code>: Spezialisierung von <code>ComponentType</code> für nicht weiter zerlegbare Softwarekomponenten.</li>\n<li><code>InternalBehavior</code> (abgeleitet von <code>ARElement</code>): Spezifiziert das interne funktionale Verhalten eines <code>AtomicSoftwareComponentType</code>.</li>\n<li>Attribut: <code>+ supportsMultipleInstantiation: Boolean</code></li>\n<li>Assoziation zu <code>AtomicSoftwareComponentType</code>: Gekennzeichnet durch die Rollenbezeichnung <code>+component</code> mit Kardinalität <code>1</code> am Komponentenende und <code>*</code> am Verhaltensende.</li>\n<li><code>RunnableEntity</code> (spezialisiert <code>ExecutableEntity</code>): Repräsentiert die kleinste ausführbare Codeeinheit (Funktion/Prozedur) innerhalb des Verhaltens.</li>\n<li>Attribute:</li>\n<li><code>+ canBeInvokedConcurrently: Boolean</code></li>\n<li><code>+ minimumStartInterval: Float</code></li>\n<li><code>+ symbol: String</code></li>\n<li>Kompositionsbeziehung: <code>InternalBehavior</code> aggregiert <code>RunnableEntity</code> als Teilkomponente (Komposition mit Rollenbezeichnung <code>+runnable</code>, Kardinalität <code>1..*</code> an <code>RunnableEntity</code> und Rolle <code>+behavior</code> an <code>InternalBehavior</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzmodellierung. Die Ausführungsparameter der <code>RunnableEntity</code> steuern das Laufzeitverhalten im RTE-Kontext: <code>canBeInvokedConcurrently</code> definiert die Reentranzfähigkeit bzw. parallele Ausführbarkeit, <code>minimumStartInterval</code> legt den Mindestabstand zwischen zwei Aktivierungen fest und <code>symbol</code> fungiert als Funktionsbezeichner für den Aufruf im generierten C-Code. Die Kompositionskardinalität <code>1..*</code> legt fest, dass ein <code>InternalBehavior</code> zur Laufzeit mindestens eine ausführbare Einheit umfassen muss.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Modellierungsregel: <code>CompositionType</code> darf kein <code>InternalBehavior</code> aggregieren; nur Instanzen von <code>AtomicSoftwareComponentType</code> dürfen über ein <code>InternalBehavior</code> verfügen.</li>\n<li>Kardinalitätsrestriktion: Ein <code>AtomicSoftwareComponentType</code> kann mit mehreren <code>InternalBehavior</code>-Elementen verknüpft sein (<code><em></code>), jedes <code>InternalBehavior</code> referenziert genau einen <code>AtomicSoftwareComponentType</code> (<code>1</code>). Jedes <code>InternalBehavior</code> muss mindestens eine <code>RunnableEntity</code> enthalten (<code>1..</em></code>).</li>\n<li>Für Entwickler und RTE-Generierung: Das Attribut <code>symbol: String</code> dient als Bezeichner für die konkrete C-Funktionssignatur der Runnable. <code>supportsMultipleInstantiation</code> steuert, ob Instanzdaten per Handle übergeben werden müssen.</li>\n</ul>"}, {"id": "FIG-8fd6b98050be1af7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells im AUTOSAR-Standard (Software Component Template). Das Diagramm stellt die strukturelle Verankerung von Ausführungseinheiten innerhalb der Softwarekomponenten-Hierarchie dar und verdeutlicht das Entwurfsprinzip, dass nur atomare Software-Komponententypen ein internes Ausführungsverhalten definieren dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Spezialisierungen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ComponentType</code> (Stereotyp «atpType», abgeleitet von <code>ARElement</code>): Abstrakte Basisklasse für alle Software-Komponententypen.</li>\n<li><code>CompositionType</code> (Stereotyp «atpType»): Spezialisierung von <code>ComponentType</code> zur hierarchischen Kapselung und Verschachtelung von Komponenten, besitzt kein eigenes <code>InternalBehavior</code>.</li>\n<li><code>AtomicSoftwareComponentType</code>: Spezialisierung von <code>ComponentType</code> für nicht weiter zerlegbare Softwarekomponenten.</li>\n<li><code>InternalBehavior</code> (abgeleitet von <code>ARElement</code>): Spezifiziert das interne funktionale Verhalten eines <code>AtomicSoftwareComponentType</code>.</li>\n<li>Attribut: <code>+ supportsMultipleInstantiation :Boolean</code></li>\n<li>Assoziation zu <code>AtomicSoftwareComponentType</code>: Gekennzeichnet durch die Rollenbezeichnung <code>+component</code> mit Kardinalität <code>1</code> am Komponentenende und <code>*</code> am Verhaltensende.</li>\n<li><code>RunnableEntity</code> (spezialisiert <code>ExecutableEntity</code>): Repräsentiert die kleinste ausführbare Codeeinheit (Funktion/Prozedur) innerhalb des Verhaltens.</li>\n<li>Attribute:</li>\n<li><code>+ canBeInvokedConcurrently :Boolean</code></li>\n<li><code>+ minimumStartInterval :Float</code></li>\n<li><code>+ symbol :CIdentifier</code></li>\n<li>Kompositionsbeziehung: <code>InternalBehavior</code> aggregiert <code>RunnableEntity</code> als Teilkomponente (Komposition mit Rollenbezeichnung <code>+runnable</code>, Kardinalität <code>1..*</code> an <code>RunnableEntity</code> und Rolle <code>+behavior</code> an <code>InternalBehavior</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite Ablauf- oder Sequenzmodellierung. Die Ausführungsparameter der <code>RunnableEntity</code> steuern das Laufzeitverhalten im RTE-Kontext: <code>canBeInvokedConcurrently</code> definiert die Reentranzfähigkeit bzw. parallele Ausführbarkeit, <code>minimumStartInterval</code> legt den Mindestabstand zwischen zwei Aktivierungen fest und <code>symbol</code> fungiert als Funktionsbezeichner für den Aufruf im generierten C-Code. Die Kompositionskardinalität <code>1..*</code> legt fest, dass ein <code>InternalBehavior</code> zur Laufzeit mindestens eine ausführbare Einheit umfassen muss.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Modellierungsregel: <code>CompositionType</code> darf kein <code>InternalBehavior</code> aggregieren; nur Instanzen von <code>AtomicSoftwareComponentType</code> dürfen über ein <code>InternalBehavior</code> verfügen.</li>\n<li>Kardinalitätsrestriktion: Ein <code>AtomicSoftwareComponentType</code> kann mit mehreren <code>InternalBehavior</code>-Elementen verknüpft sein (<code><em></code>), jedes <code>InternalBehavior</code> referenziert genau einen <code>AtomicSoftwareComponentType</code> (<code>1</code>). Jedes <code>InternalBehavior</code> muss mindestens eine <code>RunnableEntity</code> enthalten (<code>1..</em></code>).</li>\n<li>Für Entwickler und RTE-Generierung: Das Attribut <code>symbol</code> vom Typ <code>CIdentifier</code> erzwingt die Einhaltung formaler C-Bezeichner-Konventionen für den C-Funktionsnamen der Runnable. <code>supportsMultipleInstantiation</code> steuert, ob Instanzdaten per Handle übergeben werden müssen.</li>\n</ul>"}], "trans": [{"from": "FIG-7b8d4323d9df0d70", "to": "FIG-8fd6b98050be1af7", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>RunnableEntity</code>: Attributtyp von <code>symbol</code> von <code>String</code> auf <code>CIdentifier</code> geändert.</li>\n<li><code>RunnableEntity</code> und <code>InternalBehavior</code>: Redaktionelle Formatierung der Attributdeklarationen (Abstand vor dem Doppelpunkt entfallen, z. B. <code>:Boolean</code>, <code>:Float</code>, <code>:CIdentifier</code>).</li>\n</ul>"}]};
